import { execution, getWorkflowLink } from '@dynatrace-sdk/automation-utils';
import {
  credentialVaultClient,
  CredentialsDetailsTokenResponseElement,
} from '@dynatrace-sdk/client-classic-environment-v2';

// =============================================================================
// Dynatrace Host Business Hours Workflow
// =============================================================================
// This workflow checks whether the current time falls within defined business
// hours, then enables or disables host monitoring accordingly via the Dynatrace
// Settings API. After each run, it reschedules itself to fire at the opposite
// end of the business hours window.
// =============================================================================

// --- Configuration -----------------------------------------------------------

let DT_WORKFLOW_ID;
const ENV_ID = getWorkflowLink().substring(0, getWorkflowLink().indexOf("."));
const SCHEDULE_TIMEZONE = "Etc/Universal";
const DT_API_TOKEN = (await credentialVaultClient.getCredentialsDetails({ id: 'CREDENTIALS_VAULT-28A40AC58FA90F32', })).token;
const DT_BEARER_TOKEN = (await credentialVaultClient.getCredentialsDetails({ id: 'CREDENTIALS_VAULT-8F9C10F37B7FA914', })).token;

export default async function () {
    console.log("=== Host Business Hours Workflow started ===");

    const ex = await execution();
    DT_WORKFLOW_ID = ex.workflow;

    // --- 1. Parse the input object -------------------------------------------
    const input = ex.input;
    console.log("Raw input received:", input);

    const { schedule, objectIds } = input;

    if (!schedule || !objectIds || objectIds.length === 0) {
        console.error("ERROR: Input is missing 'schedule' or 'objectIds'. Aborting.");
        return;
    }

    const startHour = new Date(schedule.start).getHours();
    const endHour = new Date(schedule.end).getHours();

    console.log(`Business hours configured — Start: ${startHour}:00 | End: ${endHour}:00`);
    console.log(`Object IDs to process (${objectIds.length}):`, objectIds);

    // --- 2. Business hours check ---------------------------------------------
    // Grab the current UTC hour and compare it to the schedule.
    // If the workflow fires at schedule.start this will be true; at schedule.end it will be false.
    const nowUtc = new Date();
    const currentHour = nowUtc.getUTCHours();

    console.log(`Current UTC time: ${nowUtc.toISOString()} (hour: ${currentHour})`);

    // We consider "outside business hours" to mean: the current hour matches the
    // end time (i.e. disable hosts in the list). Any other trigger time means we 
    // should enable hosts. This means the default state should be to enable.

    const isEndOfBusinessHours = (currentHour === endHour);
    const shouldEnable = !isEndOfBusinessHours;

    if(currentHour != startHour && currentHour != endHour)
        console.log("Workflow ran between business hours. This is unintended behaviour. Hosts will be ENABLED regardless to ensure monitoring continues.")
    else
        console.log(
            isEndOfBusinessHours
                ? "Business hours are ENDING — hosts will be DISABLED."
                : "Business hours are STARTING — hosts will be ENABLED."
        );

    // --- 3 & 4. Loop over objectIds and update each settings object ----------
    console.log("\n--- Updating host monitoring settings ---");

    for (const objectId of objectIds) {
        await updateHostMonitoring(objectId, shouldEnable, DT_API_TOKEN);
    }

    // --- 5. Reschedule this workflow to fire at the opposite time ------------
    // If we just ran at START time -> reschedule to END time, and vice-versa.
    const nextHour = isEndOfBusinessHours ? startHour : endHour;
    const nextTime = formatHourAsTime(nextHour); // e.g. 17 -> "17:00"

    console.log(`\n--- Rescheduling workflow to run at ${nextTime} ---`);
    await rescheduleWorkflow(nextTime, DT_BEARER_TOKEN);

    console.log("\n=== Workflow completed successfully ===");
}

// =============================================================================
// FUNCTION: updateHostMonitoring
// Calls the Dynatrace Settings API to enable or disable monitoring for a
// single settings object identified by its objectId.
// =============================================================================
async function updateHostMonitoring(objectId, enable, DT_API_TOKEN) {
    const DT_ENVIRONMENT_URL_GEN2 = ENV_ID + ".dev.dynatracelabs.com"

    const url = `${DT_ENVIRONMENT_URL_GEN2}/api/v2/settings/objects/${objectId}`;
    const payload = {
        schemaVersion: "1.4",
        value: {
            enabled: enable
        }
    };

    console.log(`  [${objectId}] Sending PUT — enabled: ${enable}`);
    console.log(`Api-Token ${DT_API_TOKEN}`)
    try {
        const response = await fetch(url, {
            method: "PUT",
            headers: {
                "Content-Type": "application/json",
                "Authorization": `Api-Token ${DT_API_TOKEN}`
            },
            body: JSON.stringify(payload)
        });

        if (response.ok) {
            console.log(`  [${objectId}] Successfully updated (HTTP ${response.status})`);
        } else {
            const errorText = await response.text();
            console.error(`  [${objectId}] Failed (HTTP ${response.status}): ${errorText}`);
        }
    } catch (err) {
        console.error(`  [${objectId}] Network error while updating:`, err.message);
    }
}

// =============================================================================
// FUNCTION: rescheduleWorkflow
// Calls the Dynatrace Automation API to PATCH this workflow's trigger schedule
// so that the next execution fires at `nextTime` (e.g. "17:00").
// =============================================================================
async function rescheduleWorkflow(nextTime, DT_BEARER_TOKEN) {
    const DT_ENVIRONMENT_URL_GEN3 = ENV_ID + ".dev.apps.dynatracelabs.com"

    const url = `${DT_ENVIRONMENT_URL_GEN3}/platform/automation/v1/workflows/${DT_WORKFLOW_ID}`;
    const payload = {
        trigger: {
            schedule: {
                trigger: {
                    time: nextTime,  // <-- the only thing we change each run
                    type: "time"
                },
                timezone: SCHEDULE_TIMEZONE,
                inputs: {}
            }
        }
    };

    console.log(`Patching workflow ${DT_WORKFLOW_ID} — new trigger time: ${nextTime}`);

    try {
        const response = await fetch(url, {
            method: "PATCH",
            headers: {
                "Content-Type": "application/json",
                "Authorization": `Bearer ${DT_BEARER_TOKEN}`
            },
            body: JSON.stringify(payload)
        });

        if (response.ok) {
            console.log(`Workflow rescheduled to ${nextTime} (HTTP ${response.status})`);
        } else {
            const errorText = await response.text();
            console.error(`Failed to reschedule workflow (HTTP ${response.status}): ${errorText}`);
        }
    } catch (err) {
        console.error("Network error while rescheduling workflow:", err.message);
    }
}

// =============================================================================
// HELPER: formatHourAsTime
// Converts an integer hour (e.g. 9 or 17) to a zero-padded "HH:00" string.
// =============================================================================
function formatHourAsTime(hour) {
    const padded = String(hour).padStart(2, "0");
    return `${padded}:00`;
}
